// --- PROCESADO -----------------------------------------------------------------
const LEVELS = ["A2", "B1", "B2", "C1", "C2"];
const B_BASE = { A2: -1.5, B1: -0.5, B2: 0.8, C1: 1.8, C2: 2.7 };

// hash determinista (para dispersar `b` dentro de la banda, reproducible)
function hash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0) / 4294967295; // 0..1
}
// §5.2 — CEFR → b con dispersión ±0.35 según el "rank" pseudoaleatorio de la palabra
function cefrToB(cefr, word) {
  const base = B_BASE[cefr];
  const disp = (hash(word + cefr) - 0.5) * 0.7; // ±0.35
  return Math.round((base + disp) * 100) / 100;
}

const isCleanWord = (w) => /^[a-z][a-z' -]*$/i.test(w); // solo ascii, sin números ni símbolos raros

const seen = new Map();
const rejected = [];
const byLevel = { A2: 0, B1: 0, B2: 0, C1: 0, C2: 0 };

for (const batch of BATCHES) {
  for (const entry of batch) {
    if (!Array.isArray(entry) || entry.length < 3) { rejected.push(entry); continue; }
    const word = String(entry[0]).trim().toLowerCase();
    const es = String(entry[1]).trim();
    const cefr = String(entry[2]).trim().toUpperCase();
    if (!word || !es || !LEVELS.includes(cefr) || !isCleanWord(word)) { rejected.push(entry); continue; }
    if (seen.has(word)) continue;            // dedup por palabra (gana la primera aparición)
    seen.set(word, { w: word, es, cefr, b: cefrToB(cefr, word) });
    byLevel[cefr]++;
  }
}

const items = [...seen.values()].sort((a, b) => a.b - b.b);

// formato compacto: [word, es, cefr, b]
const compact = items.map((it) => [it.w, it.es, it.cefr, it.b]);
const out =
  "// Banco léxico para el examen adaptativo Lexis — generado por gen-examen-data.mjs\n" +
  "// Formato de cada ítem: [word, traducción_es, cefr, b]\n" +
  "// NO editar a mano: regenerar con `node gen-examen-data.mjs`.\n" +
  `window.LEXIS_ITEMS = ${JSON.stringify(compact)};\n`;

writeFileSync(new URL("./examen-data.js", import.meta.url), out, "utf8");

const total = items.length;
console.log("=== Banco léxico Lexis ===");
console.log("Total de términos únicos:", total);
console.log("Por nivel:", JSON.stringify(byLevel));
for (const lv of LEVELS) {
  console.log(`  ${lv}: ${byLevel[lv]}  (${((byLevel[lv] / total) * 100).toFixed(1)}%)`);
}
console.log("Rechazados/duplicados de lote ignorados:", rejected.length);
if (total < 3000) console.warn(`\n⚠️  AVISO: ${total} < 3000 términos. Hace falta otro lote.`);
else console.log(`\n✓ ${total} términos (≥ 3000). examen-data.js escrito.`);
